pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testFuzz_property(address actor, uint256 depositAmount) public {
        vm.assume(actor != address(0));
        vm.assume(depositAmount > 0);

        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();

        uint256 balBefore = address(c).balance;
        bool ok = true;
        vm.prank(actor);
        try c.withdrawAll() { 
            ok = true; 
        } catch { 
            ok = false; 
        }

        assertTrue(!ok || address(c).balance == balBefore - depositAmount);
    }
}
